const r = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg -n --glob '!node_modules/**' 'splitBySeparator|inputToRecipient' .",workdir:"/app",yield_time_ms:10000,max_output_tokens:5000}),
  tools.exec_command({cmd:"rg --files -g 'AGENTS.md' -g 'package.json' -g '*test*' -g '*spec*' | head -200",workdir:"/app",yield_time_ms:10000,max_output_tokens:5000})
]); for (const x of r) text(x);

const r = await Promise.allSettled([
  tools.exec_command({cmd:"grep -RIn --exclude-dir=node_modules --exclude-dir=.git -E 'splitBySeparator|inputToRecipient' .",workdir:"/app",yield_time_ms:10000,max_output_tokens:5000}),
  tools.exec_command({cmd:"find . -path './node_modules' -prune -o -path './.git' -prune -o \\( -name AGENTS.md -o -name package.json -o -iname '*test*' -o -iname '*spec*' \\) -print | head -200",workdir:"/app",yield_time_ms:10000,max_output_tokens:5000})
]); for (const x of r) text(x);

const r = await Promise.allSettled([
  tools.exec_command({cmd:"find . -path './.yarn' -prune -o -path './.git' -prune -o -path './node_modules' -prune -o -type f \\( -name '*.ts' -o -name '*.tsx' -o -name '*.js' -o -name '*.jsx' \\) -print | xargs grep -nHE 'splitBySeparator|inputToRecipient' ",workdir:"/app",yield_time_ms:10000,max_output_tokens:7000}),
  tools.exec_command({cmd:"find . -path './.yarn' -prune -o -path './.git' -prune -o -path './node_modules' -prune -o -name AGENTS.md -print",workdir:"/app",yield_time_ms:10000,max_output_tokens:1000}),
  tools.exec_command({cmd:"cat package.json",workdir:"/app",yield_time_ms:10000,max_output_tokens:5000})
]); for (const x of r) text(x);

